# ==============================================================================# 102_REAL_COMPANY_IMPORT_ENGINE.py# Importa empresas reais para o banco de dados do IOTEC# Cortex System LTDA# ==============================================================================import sqlite3import pandas as pdimport uuidimport hashlibfrom datetime import datetimefrom pathlib import PathDB = "iotec.db"class RealCompanyImportEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.cursor = self.conn.cursor()        self._create_table()    # -------------------------------------------------------------------------    def _create_table(self):        self.cursor.execute("""        CREATE TABLE IF NOT EXISTS commercial_master_company (            company_uuid TEXT PRIMARY KEY,            company_name TEXT,            cnpj TEXT UNIQUE,            phone TEXT,            email TEXT,            city TEXT,            state TEXT,            website TEXT,            instagram TEXT,            category TEXT,            created_at TEXT,            hash TEXT        )        """)        self.conn.commit()    # -------------------------------------------------------------------------    def _hash(self, values):        raw = "|".join([str(v) for v in values])        return hashlib.sha256(raw.encode()).hexdigest()    # -------------------------------------------------------------------------    def import_csv(self, csv_file):        csv_file = Path(csv_file)        if not csv_file.exists():            raise FileNotFoundError(csv_file)        df = pd.read_csv(csv_file)        imported = 0        updated = 0        for _, row in df.iterrows():            company = str(row.get("empresa", "")).strip()            if company == "":                continue            cnpj = str(row.get("cnpj", "")).strip()            phone = str(row.get("telefone", "")).strip()            email = str(row.get("email", "")).strip()            city = str(row.get("cidade", "")).strip()            state = str(row.get("estado", "")).strip()            website = str(row.get("website", "")).strip()            instagram = str(row.get("instagram", "")).strip()            category = str(row.get("categoria", "")).strip()            h = self._hash([                company,                cnpj,                phone,                email,                city,                state,                website,                instagram,                category            ])            self.cursor.execute("""            SELECT company_uuid            FROM commercial_master_company            WHERE cnpj=?            """, (cnpj,))            existing = self.cursor.fetchone()            if existing:                self.cursor.execute("""                UPDATE commercial_master_company                SET                    company_name=?,                    phone=?,                    email=?,                    city=?,                    state=?,                    website=?,                    instagram=?,                    category=?,                    hash=?                WHERE cnpj=?                """, (                    company,                    phone,                    email,                    city,                    state,                    website,                    instagram,                    category,                    h,                    cnpj                ))                updated += 1            else:                self.cursor.execute("""                INSERT INTO commercial_master_company                VALUES(                    ?,?,?,?,?,?,?,?,?,?,?,?                )                """, (                    str(uuid.uuid4()),                    company,                    cnpj,                    phone,                    email,                    city,                    state,                    website,                    instagram,                    category,                    datetime.now().isoformat(),                    h                ))                imported += 1        self.conn.commit()        print("=" * 60)        print("REAL COMPANY IMPORT ENGINE")        print("=" * 60)        print("Empresas importadas :", imported)        print("Empresas atualizadas:", updated)        print("=" * 60)# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    engine = RealCompanyImportEngine()    engine.import_csv("empresas.csv")